const RTL=["ar","fa","ur","he"];

const ROOT=document.getElementById('fph-l2');
const EMB=(()=>{try{return window.self!==window.top;}catch(e){return true;}})();
const $=(s,el=ROOT)=>el.querySelector(s);
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const norm=s=>s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').replace(/[^a-z ]/g,' ').replace(/\s+/g,' ').trim();
const esc=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/"/g,'&quot;');

/* ---------- Langue des consignes ---------- */
let LANG='en',SEL='GB|English';
const fr=k=>I18N.fr[k]||k;
const tr=k=>LANG==='fr'?'':((I18N[LANG]||I18N.en)[k]||I18N.en[k]||'');
const T=k=>k?`<span class="tri" dir="auto" data-k="${k}"></span>`:'';
const TB=k=>`<span class="tr" dir="auto" data-k="${k}"></span>`;
function paintTr(root=document){root.querySelectorAll('[data-k]').forEach(e=>{const t=tr(e.dataset.k);e.textContent=t?'('+t+')':'';});}
/* ---------- Menu des langues : tous les pays du monde, ordre alphabétique, recherche ---------- */
const FLAG=iso=>/^[A-Z]{2}$/.test(iso)?String.fromCodePoint(...[...iso].map(c=>0x1F1E6+c.charCodeAt(0)-65)):'🌐';
const sn=s=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
const ENT=COUNTRIES.map(([n,iso,lab,code,fb,nfr])=>({id:iso+'|'+lab,n,iso,lab,code,fb,nfr}));
function regionName(loc,iso){try{if(!Intl.DisplayNames.supportedLocalesOf([loc]).length)return '';return new Intl.DisplayNames([loc],{type:'region'}).of(iso)||'';}catch(e){return '';}}
let IDX=null;function buildIdx(){if(IDX)return;IDX=ENT.map(e=>{const nat=regionName(e.code,e.iso),en=regionName('en',e.iso);e.nat=(nat&&e.code!=='en'&&sn(nat)!==sn(e.n)&&sn(nat)!==sn(en)&&nat!==e.iso)?nat:'';return sn([e.n,e.nfr,e.lab,LNAME[e.code],e.code,e.iso,nat,en].join(' '));});}
function guessSel(){const L=(navigator.languages&&navigator.languages.length?navigator.languages:[navigator.language||'en']);
  for(const l of L){const [b,r]=l.split(/[-_]/);const code=(b==='zh'&&/TW|HK|MO|Hant/i.test(l))?'zh-Hant':b;
    let e=r&&ENT.find(x=>x.iso===r.toUpperCase()&&x.code===code&&!x.fb);if(e)return e.id;
    e=ENT.find(x=>x.code===code&&!x.fb&&({en:'GB',fr:'FR',es:'ES',pt:'PT',ar:'SA',zh:'CN',de:'DE',it:'IT',ru:'RU',nl:'NL',sw:'TZ',hi:'IN',ja:'JP',ko:'KR'}[code]||x.iso)===x.iso);if(e)return e.id;
    e=ENT.find(x=>x.code===code&&!x.fb);if(e)return e.id;}
  return 'GB|English';}
function setSel(id,save){const e=ENT.find(x=>x.id===id)||ENT.find(x=>x.id==='GB|English');SEL=e.id;LANG=e.code;
  if(save)try{localStorage.setItem('fph-sel',SEL);}catch(e){}
  const b=$('#langsel .lt');if(b){b.textContent=e.lab.replace(/ → .*/,'');b.parentNode.title=`${e.n} (${e.lab})`;}document.documentElement.dataset.tr=LANG;paintTr();}
function initLang(){const host=$('#langsel');
  host.innerHTML=`<button class="lbtn" type="button" aria-haspopup="listbox" aria-expanded="false" title="Langue / Language / Idioma / 语言 / اللغة">🌐 <span class="lt"></span> ▾</button>
   <div class="lpanel" role="dialog" aria-label="Langue des traductions / Translation language"><input type="search" placeholder="🔎 Country, language… / Pays, langue… / País… / 国家… / بلد…" aria-label="Search a country or a language"><div class="llist" role="listbox"></div></div>`;
  const btn=$('.lbtn',host),pan=$('.lpanel',host),inp=$('input',pan),list=$('.llist',pan);let act=-1,shown=[];
  const render=()=>{buildIdx();const q=sn(inp.value.trim());const rk=i=>{const e=ENT[i];return sn(e.n).startsWith(q)?0:(sn(e.lab).startsWith(q)||(' '+IDX[i]).includes(' '+q))?1:2;};shown=ENT.map((e,i)=>[e,i]).filter(([e,i])=>!q||IDX[i].includes(q)).map(([e,i])=>[e,q?rk(i):0,i]).sort((x,y)=>x[1]-y[1]||x[2]-y[2]).map(x=>x[0]);act=shown.length?0:-1;
    list.innerHTML=shown.length?shown.map((e,i)=>`<button type="button" role="option" class="lopt ${e.id===SEL?'on':''} ${i===act&&q?'act':''}" data-id="${esc(e.id)}"><span class="fl">${FLAG(e.iso)}</span><span class="nm">${e.n} <span class="ll">(${e.lab})</span>${e.nat?`<span class="nat" dir="auto">${e.nat}</span>`:''}</span></button>`).join(''):'<div class="lempty">🔎 ∅</div>';
    if(!q){const on=list.querySelector('.on');if(on)on.scrollIntoView({block:'center'});}};
  const open=o=>{pan.classList.toggle('open',o);btn.setAttribute('aria-expanded',o);if(o){inp.value='';render();setTimeout(()=>inp.focus(),30);}};
  btn.onclick=()=>open(!pan.classList.contains('open'));
  inp.oninput=render;
  inp.onkeydown=e=>{if(e.key==='Escape'){open(false);btn.focus();}
    else if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!shown.length)return;act=(act+(e.key==='ArrowDown'?1:-1)+shown.length)%shown.length;list.querySelectorAll('.lopt').forEach((b,i)=>b.classList.toggle('act',i===act));list.children[act].scrollIntoView({block:'nearest'});}
    else if(e.key==='Enter'&&act>=0){setSel(shown[act].id,true);open(false);}};
  list.onclick=e=>{const b=e.target.closest('.lopt');if(!b)return;setSel(b.dataset.id,true);open(false);};
  document.addEventListener('click',e=>{if(!host.contains(e.target))open(false);});
  let saved='';try{saved=localStorage.getItem('fph-sel')||'';}catch(e){}
  setSel(saved&&ENT.some(x=>x.id===saved)?saved:guessSel(),false);}

/* ---------- Voix : homme, femme, enfant, ado, senior ---------- */
let VOICES=[];const hasTTS='speechSynthesis' in window;
function loadVoices(){if(hasTTS)VOICES=speechSynthesis.getVoices();}
if(hasTTS){loadVoices();speechSynthesis.onvoiceschanged=loadVoices;}
const MALE=/(paul|henri|thomas|claude|r[ée]my|jean|antoine|mathieu|nicolas|yves|g[ée]rard|daniel|guillaume|vincent|fabrice|alain|male|homme|frd|frb)/i;
const FEMALE=/(denise|julie|hortense|am[ée]lie|audrey|aur[ée]lie|marie|virginie|c[ée]line|eloise|[ée]lo[iï]se|l[ée]a|female|femme|fra|frc|google fran)/i;
/* code : [genre de la voix, hauteur si voix trouvée, vitesse, hauteur si voix inconnue] */
const VP={M:['M',1,.9,.85],F:['F',1,.9,1.2],C:['F',1.35,.92,1.5],Tg:['F',1.12,.92,1.28],Tg2:['F',1.05,.92,1.2],Tb:['M',1.08,.92,1.0],Sm:['M',.9,.86,.8],Sm2:['M',.96,.88,.88],Sf:['F',.94,.86,1.1]};
function pickVoice(g,lang){
  if(lang&&!lang.startsWith('fr')){const pre=lang.slice(0,2);return VOICES.find(v=>v.lang&&v.lang.replace('_','-').toLowerCase()===lang.toLowerCase())||VOICES.find(v=>v.lang&&v.lang.toLowerCase().startsWith(pre))||null;}
  const f=VOICES.filter(v=>/^fr/i.test(v.lang));if(!f.length)return null;
  const re=g==='F'?FEMALE:MALE, other=g==='F'?MALE:FEMALE;
  /* la voix la plus claire : naturelle/neuronale > Google > fr-FR > genre correspondant */
  const sc=v=>(/natural|neural|online|premium|enhanced/i.test(v.name)?8:0)+(/google/i.test(v.name)?3:0)+(/^fr[-_]fr/i.test(v.lang)?4:0)+(re.test(v.name)?6:other.test(v.name)?-6:0)+(v.localService===false?1:0);
  return f.slice().sort((a,b)=>sc(b)-sc(a))[0];
}
let AUD=null;
function playFile(text,o){const A1=CONFIG.audio||{},A2=CONFIG.audioSlow||{};const url=o.slow?(A2[text]||A1[text]):A1[text];if(!url)return false;
  try{if(hasTTS)speechSynthesis.cancel();}catch(e){}if(AUD){try{AUD.pause();}catch(e){}}
  AUD=new Audio(url);if(o.slow&&!A2[text])AUD.playbackRate=.7;const fin=()=>{o.onend&&o.onend();};AUD.onended=fin;AUD.onerror=fin;AUD.play().catch(fin);return true;}
function speak(text,o={}){
  if(playFile(text,o))return;
  if(!hasTTS){toast('🔇 Audio : Chrome, Edge, Safari.');return;}
  const p=VP[o.g]||VP.M,u=new SpeechSynthesisUtterance(text);u.lang=o.lang||'fr-FR';
  const v=pickVoice(p[0],o.lang);if(v)u.voice=v;
  const matched=v&&(p[0]==='F'?FEMALE:MALE).test(v.name);
  u.rate=o.slow?.6:p[2];u.pitch=(o.lang&&!o.lang.startsWith('fr'))?1:(matched?p[1]:p[3]);
  if(o.onend){u.onend=o.onend;u.onerror=o.onend;}
  if(!o.queue)speechSynthesis.cancel();speechSynthesis.speak(u);return u;
}
let PLAY=0;
function playLines(lines,o={}){/* lines : [[nom,voix,texte],…] ; o.gap = pause pour répéter */
  if(!hasTTS&&!Object.keys(CONFIG.audio||{}).length){speak('');return;}try{speechSynthesis.cancel();}catch(e){}const id=++PLAY;let i=0;
  const next=()=>{if(id!==PLAY||i>=lines.length){o.done&&id===PLAY&&o.done();return;}const [n,g,t]=lines[i];o.each&&o.each(i);i++;
    speakSafe(t,{g,slow:o.slow,queue:true},()=>setTimeout(next,o.gap||250));};next();}
/* onend de secours (certains navigateurs ne le déclenchent pas) */
function speakSafe(t,o,cb){let f=false;const fin=()=>{if(f)return;f=true;cb&&cb();};speak(t,Object.assign({},o,{onend:fin}));setTimeout(fin,(700+t.length*95)*(o.slow?1.7:1));}
function stopAudio(){PLAY++;if(AUD){try{AUD.pause();}catch(e){}AUD=null;}if(hasTTS)speechSynthesis.cancel();}
const A=(text,g='M',lang)=>`<span class="aus"><button class="au" data-t="${encodeURIComponent(text)}" data-g="${g}" ${lang?`data-l="${lang}"`:''} title="Écouter (Listen)" aria-label="Écouter : ${esc(text)}">🔊</button><button class="au slow" data-t="${encodeURIComponent(text)}" data-g="${g}" ${lang?`data-l="${lang}"`:''} data-s="1" title="Lentement (Slowly)" aria-label="Écouter lentement : ${esc(text)}">🐢</button></span>`;
const S=(text,g='M')=>`<span class="say">${text} ${A(text,g)}</span>`;
document.addEventListener('click',e=>{const b=e.target.closest('.au');if(!b)return;e.stopPropagation();e.preventDefault();PLAY++;
  speak(decodeURIComponent(b.dataset.t),{g:b.dataset.g,slow:!!b.dataset.s,lang:b.dataset.l});},true);

