const SW=(t,g='M')=>`<span class="sw"><span class="w">${t}</span>${A(t,g)} ${T(EXP[t])}</span>`;

function toast(m){const t=document.createElement('div');t.textContent=m;Object.assign(t.style,{position:'fixed',left:'50%',bottom:'20px',transform:'translateX(-50%)',background:'#24203A',color:'#fff',padding:'12px 18px',borderRadius:'14px',zIndex:300,fontWeight:700,maxWidth:'90%'});ROOT.appendChild(t);setTimeout(()=>t.remove(),3500);}
function confetti(){const e=['🎉','⭐','👏','💜','🇫🇷'];for(let i=0;i<18;i++){const c=document.createElement('div');c.className='confetti';c.textContent=e[i%e.length];c.style.left=Math.random()*100+'vw';c.style.animationDelay=Math.random()*.6+'s';ROOT.appendChild(c);setTimeout(()=>c.remove(),3000);}}
function hint(target){if(!target||!target.isConnected)return;const r=target.getBoundingClientRect(),p=$('#stage').getBoundingClientRect();const h=document.createElement('div');h.className='hint';h.textContent='👆';h.style.left=(r.left-p.left+r.width/2-10)+'px';h.style.top=(r.top-p.top+r.height/2-6)+'px';$('#stage').appendChild(h);setTimeout(()=>h.remove(),3200);}
