Object.assign(ICON,{L_c9d:'👔✍️',L_c9e:'😊✍️',L_gm1:'🧠🃏',L_gm2:'👂👆',L_gm3:'🔤👆',L_gm4:'👔😊',L_gm5:'👂🗣️',L_t1:'🎧👆',L_t2:'📖👆',L_t3:'✍️',L_t4:'🗣️🎙️',fi_c:'👂👆',os_c1:'👂🎙️🔁',os_w1:'💬✍️',os_w2:'📧✍️',md_1:'🔄🥖',md_2:'🔄💬',nb_copy:'✍️📓'});
