/* =========== 8. J'ÉCRIS =========== */
function dragDrop(host,onDone){
  const P=[['salutAmis','Tu t\'appelles comment ?'],['hotel','Comment vous appelez-vous ?'],['paul','Enchanté !'],['elara','Enchantée !']];
  const words=shuffle(['Tu t\'appelles comment ?','Comment vous appelez-vous ?','Enchanté !','Enchantée !','Et toi ?','Bonsoir !']);
  host.innerHTML=`<div class="grid g4f pd">${P.map(([img,a])=>`<div class="card" style="text-align:center">${IMG(img)}<span class="slot" data-a="${esc(a)}"></span></div>`).join('')}</div>
   <p style="font-weight:800;margin:14px 0 6px;text-align:center">✋ ⬆️</p><div class="tiles"></div>
   <div class="row center" style="margin-top:14px"><button class="btn vb">✔ ${fr('check')} ${T('check')}</button><button class="btn sec rs">↻</button></div><div class="fb" style="text-align:center"></div>`;
  const tiles=$('.tiles',host);let sel=null;
  const place=(slot,tile)=>{if(slot.dataset.v){const old=[...tiles.querySelectorAll('.tile.used')].find(x=>x.dataset.w===slot.dataset.v);if(old)old.classList.remove('used');}
    slot.textContent=tile.dataset.w;slot.dataset.v=tile.dataset.w;slot.className='slot filled';tile.classList.add('used');tile.classList.remove('sel');sel=null;speak(tile.dataset.w);};
  words.forEach((w,i)=>{const t=document.createElement('div');t.className='tile';t.textContent=w;t.dataset.w=w;if(i===0)t.dataset.hint=1;tiles.appendChild(t);
    t.addEventListener('pointerdown',e=>{if(t.classList.contains('used'))return;e.preventDefault();const r=t.getBoundingClientRect();const sx=e.clientX,sy=e.clientY;let moved=false,gh=null,over=null;
      const mv=ev=>{if(!moved&&Math.hypot(ev.clientX-sx,ev.clientY-sy)<6)return;if(!moved){moved=true;gh=t.cloneNode(true);gh.classList.add('ghost');gh.style.width=r.width+'px';ROOT.appendChild(gh);t.style.opacity=.35;}
        gh.style.left=(ev.clientX-r.width/2)+'px';gh.style.top=(ev.clientY-r.height/2)+'px';const el=document.elementFromPoint(ev.clientX,ev.clientY);const s=el&&el.closest('.slot');if(over&&over!==s)over.classList.remove('hover');over=s;if(s)s.classList.add('hover');};
      const up=ev=>{window.removeEventListener('pointermove',mv);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);t.style.opacity='';
        if(moved){gh&&gh.remove();if(over){over.classList.remove('hover');place(over,t);}}
        else{tiles.querySelectorAll('.tile').forEach(x=>x.classList.remove('sel'));sel=t;t.classList.add('sel');speak(w);}};
      window.addEventListener('pointermove',mv);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up);});});
  host.querySelectorAll('.slot').forEach(s=>s.onclick=()=>{if(sel){place(s,sel);return;}if(s.dataset.v){const old=[...tiles.querySelectorAll('.tile.used')].find(x=>x.dataset.w===s.dataset.v);if(old)old.classList.remove('used');s.textContent='';delete s.dataset.v;s.className='slot';}});
  $('.rs',host).onclick=()=>dragDrop(host,onDone);
  $('.vb',host).onclick=()=>{let ok=0;const all=host.querySelectorAll('.slot');all.forEach(s=>{const g=s.dataset.v===s.dataset.a;s.classList.toggle('ok',g);s.classList.toggle('ko',!g);if(g)ok++;});
    const f=$('.fb',host);if(ok===all.length){setFb(f,true,fbOK('bravo',`${ok}/${all.length}`));confetti();}else{setFb(f,false,fbKO('again',`${ok}/${all.length}`)+(LOCK?` · 🔁 ${fr('L_redo')} ${T('L_redo')}`:''));
      if(LOCK)setTimeout(()=>all.forEach(s=>{if(!s.classList.contains('ko'))return;const old=[...tiles.querySelectorAll('.tile.used')].find(x=>x.dataset.w===(s.dataset.v||''));if(old)old.classList.remove('used');s.textContent='';delete s.dataset.v;s.className='slot';}),1500);}onDone(ok,all.length);};
  paintTr(host);
}
