  bw.innerHTML=`<div class="card"><p style="margin:0 0 6px"><b>Prénom</b> ${T('l2_first')}<br><input type="text" class="bp" placeholder="Amina" style="width:100%"></p><p style="margin:6px 0 0"><b>Nom</b> ${T('l2_last')}<br><input type="text" class="bn" placeholder="DIALLO" style="width:100%"></p></div>
    <div><div class="badgecard big"><div class="bh">French Practice Hub · 🎫</div><div class="bt">Bonjour ! Je m'appelle <b class="bpv">…</b> <b class="bnv"></b>.</div></div>
    <div class="row" style="margin-top:8px"><button class="btn jaune sm blu">🔊</button><button class="btn sm bsend">📤 ${fr('os_send')} ${T('os_send')}</button></div><div class="fb bfb"></div><div class="schip"></div></div>`;
  const bupd=()=>{const pr=$('.bp',bw).value.trim(),no=$('.bn',bw).value.trim().toUpperCase();$('.bpv',bw).textContent=pr||'…';$('.bnv',bw).textContent=no;return {pr,no,t:`Bonjour ! Je m'appelle ${pr} ${no}.`};};
  bw.querySelectorAll('input').forEach(x=>x.addEventListener('input',bupd));
  $('.blu',bw).onclick=()=>speak(bupd().t,{g:'M'});
  $('.bsend',bw).onclick=()=>{const b=bupd();if(b.pr.length<2||b.no.length<2){setFb($('.bfb',bw),false,`💡 ${fr('tip_name')} ${T('tip_name')}`);return;}setFb($('.bfb',bw),true,fbOK());award('badgeW','EE',2,2);doneK('badgeW');
    sendProd({activity:'badge',label:fr('l2_c8c'),register:'',mode:'écrit',text:b.t},$('.schip',bw));};
  /* messages : formel puis informel */
  const MSG=[
   {id:'mf',k:'l2_c9d',img:'bureau',badge:'👔 '+fr('L_formal'),tk:'L_formal',formal:1,G:[['g1',['Bonjour','Bonsoir','Salut'],0],['gt',['monsieur','madame'],0],['g3',['Enchanté !','Enchantée !'],-1],['g4',['Au revoir !','Bonne journée !'],-1]],to:'Diallo'},
   {id:'mi',k:'l2_c9e',img:'soeur',badge:'😊 '+fr('L_informal'),tk:'L_informal',formal:0,G:[['g1',['Salut','Bonjour'],0],['g3',['Tu t\'appelles comment ?','Comment vous appelez-vous ?'],-1],['g4',['À bientôt !','Salut !'],-1]],to:''}];
