  $('.play3',d).onclick=()=>{const rows=d.querySelectorAll('.turn');playLines(RP.map(([n,g,t])=>[n,g,t]),{gap:350,each:i=>{rows.forEach((r,j)=>r.classList.toggle('now',j===i));},done:()=>rows.forEach(r=>r.classList.remove('now'))});};
