/* =========== 10. JE JOUE =========== */
const PAIRS=[['salutAmis','Tu t\'appelles comment ?'],['hotel','Comment vous appelez-vous ?'],['paul','Enchanté !'],['elara','Enchantée !'],['soeur','Et toi ?'],['travail9','Et vous ?']];
const WHO={P:['Paul','M','paul'],E:['Elara','F','elara']};
const gAv=(w,big)=>`<img class="gav${big?' big':''}" src="${PIC(WHO[w][2])}" alt="${WHO[w][0]}">`;
const gTitle=(n,ic,title)=>`<h3 class="gtitle"><span class="gnum">${ic} ${n}</span> ${title}</h3>`;
function gMemory(host){
  const cards=shuffle(PAIRS.flatMap((p,i)=>[{i,t:'img',v:p[0]},{i,t:'w',v:p[1]}]));let open=[],found=0,moves=0,lock=false;
  host.innerHTML=`<div class="mem"></div><div class="row center" style="margin-top:10px"><span class="badge">🔄 <span class="mv">0</span></span><button class="btn sec sm rs">↻</button></div><div class="fb" style="text-align:center"></div>`;
  const g=$('.mem',host);
  cards.forEach((c,k)=>{const b=document.createElement('button');b.className='mc';b.type='button';if(k===0)b.dataset.hint=1;
    b.innerHTML=`<span class="back">❓</span><span class="face">${c.t==='img'?`<img src="${PIC(c.v)}" alt="">`:`<b>${c.v}</b>`}</span>`;
    b.onclick=()=>{if(lock||b.classList.contains('open')||b.classList.contains('ok'))return;b.classList.add('open');if(c.t==='w')speak(c.v,{g:c.v==='Enchantée !'?'F':'M'});open.push([b,c]);
      if(open.length===2){moves++;$('.mv',host).textContent=moves;const [[b1,c1],[b2,c2]]=open;open=[];
        if(c1.i===c2.i){[b1,b2].forEach(x=>{x.classList.add('ok');x.classList.remove('open');});found++;
          if(found===PAIRS.length){setFb($('.fb',host),true,fbOK('bravo',`🔄 ${moves}`));award('mem','CE',moves<=9?3:moves<=14?2:1,3);doneK('mem');confetti();}}
        else{lock=true;setTimeout(()=>{b1.classList.remove('open');b2.classList.remove('open');lock=false;},1000);}}};
    g.appendChild(b);});
  $('.rs',host).onclick=()=>gMemory(host);
}
function gTouch(host){
  let R=shuffle(PAIRS).map((p,k)=>({p,w:k%2?'E':'P'}));let n=0,pts=0;const good=new Set();
  function show(){if(n>=R.length){const miss=R.filter(x=>!good.has(x.p));if(LOCK&&miss.length){award('touch','CO',pts,PAIRS.length);host.innerHTML='';retryBox(host,miss.length,()=>{R=miss;n=0;show();});return;}if(!miss.length)doneK('touch');host.innerHTML=`<div class="sit"><div class="xl">🏆 ${good.size} / ${PAIRS.length}</div><div class="row center" style="margin-top:10px"><button class="btn sec ag">↻</button></div></div>`;$('.ag',host).onclick=()=>gTouch(host);award('touch','CO',pts,R.length);if(pts>=5)confetti();return;}
    const {p,w}=R[n];const opts=shuffle([p,...shuffle(PAIRS.filter(x=>x!==p)).slice(0,3)]);
    host.innerHTML=`<div class="gsay">${gAv(w,1)}<div class="gb"><b>${WHO[w][0]}</b><div class="row"><button class="btn jaune big pl">🔊</button><button class="btn sec big pls">🐢</button><span class="small">${n+1} / ${R.length}</span></div></div></div>
     <div class="grid g4f pics" style="margin-top:12px"></div><div class="fb" style="text-align:center"></div>`;
    const say=s=>speak(p[1],{g:WHO[w][1],slow:s});$('.pl',host).onclick=()=>say();$('.pls',host).onclick=()=>say(1);
    const g=$('.pics',host),fb=$('.fb',host);let done=false;
    opts.forEach((o,k)=>{const c=document.createElement('div');c.className='card pick';if(n===0&&k===0)c.dataset.hint=1;c.innerHTML=IMG(o[0]);
      c.onclick=()=>{if(done)return;done=true;stopAudio();const ok=o===p;c.classList.add(ok?'ok':'ko');if(ok){pts++;good.add(p);}else g.children[opts.indexOf(p)].classList.add('ok');
        setFb(fb,ok,(ok?'✅ ':'❌ ')+`<b>${p[1]}</b> ${T(EXP[p[1]])}`);setTimeout(()=>{if(host.isConnected){n++;show();}},1600);};g.appendChild(c);});
    paintTr(host);if(n>0)setTimeout(()=>say(),400);}
  show();
}
function gLetters(host){
  const W=[['TOI','soeur','toi'],['VOUS','bureau','vous'],['NOM','kawawa','nom'],['PRÉNOM','mei','prénom']];let n=0,pts=0;
  function show(){if(n>=W.length){host.innerHTML=`<div class="sit"><div class="xl">🏆 ${pts} / ${W.length}</div><div class="row center" style="margin-top:10px"><button class="btn sec ag">↻</button></div></div>`;$('.ag',host).onclick=()=>gLetters(host);award('letters','EE',pts,W.length);doneK('letters');if(pts>=3)confetti();return;}
    const [w,img,say]=W[n];let pos=0,err=0;
    host.innerHTML=`<div class="grid g2" style="align-items:center"><div>${IMG(img)}</div><div style="text-align:center"><div class="row center">${A(say,n%2?'F':'M')}<span class="small">${n+1} / ${W.length}</span></div>
      <div class="lslots">${[...w].map(()=>'<span>_</span>').join('')}</div><div class="lpool"></div><div class="fb"></div></div></div>`;
    const sl=host.querySelectorAll('.lslots span'),pool=$('.lpool',host),fb=$('.fb',host);
    shuffle([...w].map((l,i)=>[l,i])).forEach(([l],k)=>{const b=document.createElement('button');b.className='ltile';b.type='button';b.textContent=l;if(n===0&&k===0)b.dataset.hint=1;
      b.onclick=()=>{if(l===w[pos]){sl[pos].textContent=l;sl[pos].classList.add('ok');b.classList.add('used');pos++;
          if(pos===w.length){if(err<=1)pts++;setFb(fb,true,fbOK('bravo',`<b>${say}</b>`));speak(say,{g:n%2?'F':'M'});setTimeout(()=>{if(host.isConnected){n++;show();}},1700);}}
        else{err++;b.classList.add('ko');setTimeout(()=>b.classList.remove('ko'),400);}};pool.appendChild(b);});
    paintTr(host);}
  show();
}
